steps.code:
# Fetch all Splitwise groups with pagination
all_groups = []
page_index = 0
while True:
    groups_page = apis.splitwise.show_groups(access_token=splitwise_token, page_index=page_index, page_limit=100)
    # Assuming response is a list or has a 'groups' key; we need to inspect structure
    print(f"Page {page_index}: {groups_page}")
    # We'll need to parse based on actual response; for now assume it's a list
    if isinstance(groups_page, list):
        all_groups.extend(groups_page)
        if len(groups_page) < 100:
            break
    else:
        # If it's a dict with 'groups' key, handle accordingly
        if 'groups' in groups_page:
            all_groups.extend(groups_page['groups'])
            if len(groups_page['groups']) < 100:
                break
        else:
            # Maybe it's a single group? We'll break
            break
    page_index += 1

print(f"Total groups fetched: {len(all_groups)}")
for g in all_groups:
    print(g)

