steps.code:
# Build name to email mapping from all groups
name_to_email = {}
for group in all_groups:
    for member in group['members']:
        name = member['name']
        email = member['email']
        if name not in name_to_email:
            name_to_email[name] = email
        # Optionally check consistency
        elif name_to_email[name] != email:
            print(f"Warning: {name} has multiple emails: {name_to_email[name]} vs {email}")

print("Name to email mapping:")
for name, email in name_to_email.items():
    print(f"{name}: {email}")

